             Ok(frame) => {
                 &&& frame.inv()
                 &&& final(auth)@ == old(auth)@.spec_alloc_one(frame@)
                 &&& final(auth)@.frames.allocated_frames.contains(frame@)
                 &&& final(auth)@.frames.refcounts[frame@] == 1
             },
             Err(_) => final(auth)@ == old(auth)@,
         },

